CREATE TABLE "auth_challenges" ("id" uuid NOT NULL, "kind" character varying NOT NULL, "provider" character varying NULL, "issuer" character varying NULL, "bff_flow_id" uuid NULL, "context_hash" bytea NOT NULL, "session_binding_hash" bytea NULL, "target_identity_id" uuid NULL, "provider_config_version" bigint NULL, "proof_ciphertext" bytea NULL, "proof_key_id" character varying NULL, "email_token_hash" bytea NULL, "email_expires_at" timestamptz NULL, "confirmed_at" timestamptz NULL, "status" character varying NOT NULL DEFAULT 'issued', "result_mutation_id" character varying NULL, "result_request_hash" bytea NULL, "result_user_id" uuid NULL, "result_expires_at" timestamptz NULL, "auth_version" bigint NULL, "return_app_id" character varying NOT NULL DEFAULT '', "return_path" character varying NOT NULL DEFAULT '', "expires_at" timestamptz NOT NULL, "consumed_at" timestamptz NULL, "created_at" timestamptz NOT NULL, "user_id" uuid NULL, PRIMARY KEY ("id"), CONSTRAINT "auth_challenges_users_user" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "auth_challenges_completed" CHECK (((status)::text <> 'completed'::text) OR (consumed_at IS NOT NULL)), CONSTRAINT "auth_challenges_context" CHECK ((octet_length(context_hash) = 32) AND ((session_binding_hash IS NULL) OR (octet_length(session_binding_hash) = 32))), CONSTRAINT "auth_challenges_email_hash" CHECK ((email_token_hash IS NULL) OR (octet_length(email_token_hash) = 32)), CONSTRAINT "auth_challenges_expiry" CHECK (expires_at > created_at), CONSTRAINT "auth_challenges_issuer" CHECK ((provider IS NULL) OR (((provider)::text = 'google'::text) AND ((issuer)::text = 'https://accounts.google.com'::text)) OR (((provider)::text = 'github'::text) AND ((issuer)::text = 'https://github.com'::text))), CONSTRAINT "auth_challenges_kind" CHECK ((kind)::text = ANY ((ARRAY['external_login'::character varying, 'external_registration'::character varying, 'identity_link'::character varying, 'identity_unlink'::character varying, 'set_password'::character varying, 'recovery'::character varying, 'account_deletion'::character varying])::text[])), CONSTRAINT "auth_challenges_kind_owner" CHECK ((((kind)::text = ANY ((ARRAY['external_login'::character varying, 'external_registration'::character varying])::text[])) AND (user_id IS NULL)) OR (((kind)::text <> ALL ((ARRAY['external_login'::character varying, 'external_registration'::character varying])::text[])) AND (user_id IS NOT NULL))), CONSTRAINT "auth_challenges_kind_provider" CHECK (((kind)::text <> ALL ((ARRAY['external_login'::character varying, 'external_registration'::character varying, 'identity_link'::character varying])::text[])) OR (provider IS NOT NULL)), CONSTRAINT "auth_challenges_owner" CHECK (((user_id IS NULL) AND (auth_version IS NULL) AND (session_binding_hash IS NULL)) OR ((user_id IS NOT NULL) AND (auth_version IS NOT NULL) AND (auth_version >= 1) AND (session_binding_hash IS NOT NULL))), CONSTRAINT "auth_challenges_proof" CHECK ((proof_ciphertext IS NULL) = (proof_key_id IS NULL)), CONSTRAINT "auth_challenges_provider" CHECK (((provider IS NULL) AND (issuer IS NULL) AND (provider_config_version IS NULL)) OR ((provider IS NOT NULL) AND ((provider)::text = ANY ((ARRAY['google'::character varying, 'github'::character varying])::text[])) AND (issuer IS NOT NULL) AND (provider_config_version IS NOT NULL) AND (provider_config_version >= 1))), CONSTRAINT "auth_challenges_result" CHECK (((result_mutation_id IS NULL) AND (result_request_hash IS NULL) AND (result_user_id IS NULL) AND (result_expires_at IS NULL)) OR (((status)::text = 'completed'::text) AND (result_mutation_id IS NOT NULL) AND ((char_length((result_mutation_id)::text) >= 1) AND (char_length((result_mutation_id)::text) <= 64)) AND (result_request_hash IS NOT NULL) AND (result_user_id IS NOT NULL) AND (result_expires_at IS NOT NULL))), CONSTRAINT "auth_challenges_result_hash" CHECK ((result_request_hash IS NULL) OR (octet_length(result_request_hash) = 32)), CONSTRAINT "auth_challenges_status" CHECK ((status)::text = ANY ((ARRAY['issued'::character varying, 'exchanging'::character varying, 'ready'::character varying, 'completed'::character varying, 'failed'::character varying])::text[])), CONSTRAINT "auth_challenges_target" CHECK (((kind)::text <> 'identity_unlink'::text) OR (target_identity_id IS NOT NULL)));
